import React, { useState } from 'react';
import { X, Plus, Save } from 'lucide-react';

// Form field definitions for each sheet type
const formFields = {
    order_booked: [
        { name: 'date', label: 'Date', type: 'date', required: true },
        { name: 'customer_name', label: 'Customer Name', type: 'text', required: true },
        { name: 'order_id', label: 'Order ID', type: 'text', required: true },
        { name: 'product', label: 'Product', type: 'text', required: true },
        { name: 'amount', label: 'Amount', type: 'number', required: true },
        { name: 'status', label: 'Status', type: 'select', options: ['Pending', 'Confirmed', 'Delivered'], required: true },
        { name: 'region', label: 'Region', type: 'text', required: false },
    ],
    payment_collection: [
        { name: 'date', label: 'Date', type: 'date', required: true },
        { name: 'invoice_no', label: 'Invoice No', type: 'text', required: true },
        { name: 'customer_name', label: 'Customer Name', type: 'text', required: true },
        { name: 'amount', label: 'Amount', type: 'number', required: true },
        { name: 'payment_status', label: 'Payment Status', type: 'select', options: ['Pending', 'Received', 'Partial'], required: true },
        { name: 'payment_mode', label: 'Payment Mode', type: 'select', options: ['Cash', 'Cheque', 'Online', 'Wire Transfer'], required: false },
    ],
    funnel: [
        { name: 'stage', label: 'Stage', type: 'text', required: true },
        { name: 'count', label: 'Count', type: 'number', required: true },
        { name: 'value', label: 'Value', type: 'number', required: true },
        { name: 'conversion_rate', label: 'Conversion Rate (%)', type: 'number', required: false },
    ],
    proposal_submitted: [
        { name: 'date', label: 'Date', type: 'date', required: true },
        { name: 'pot_id', label: 'POT ID', type: 'text', required: false },
        { name: 'client_name', label: 'Client Name', type: 'text', required: true },
        { name: 'sales_person', label: 'Sales Person', type: 'text', required: true },
        { name: 'opportunity_name', label: 'Opportunity Name', type: 'text', required: true },
        { name: 'tcv', label: 'TCV (₹Cr)', type: 'number', required: true },
        { name: 'acv', label: 'ACV (₹Cr)', type: 'number', required: false },
        { name: 'mrr', label: 'MRR (₹Cr)', type: 'number', required: false },
        { name: 'otc', label: 'OTC (₹Cr)', type: 'number', required: false },
        { name: 'probability', label: 'Probability (%)', type: 'number', required: true },
        { name: 'sales_stage', label: 'Sales Stage', type: 'select', options: ['L1', 'L2', 'L3', 'L4', 'L5', 'L6'], required: true },
        { name: 'sales_type', label: 'Sales Type', type: 'select', options: ['Net New', 'Upsell', 'Existing'], required: true },
        { name: 'industry', label: 'Industry', type: 'text', required: true },
        { name: 'region', label: 'Region', type: 'text', required: true },
        { name: 'source', label: 'Source', type: 'select', options: ['Direct', 'Channel', 'Alliance Partner'], required: false },
    ],
    demos: [
        { name: 'sales_person', label: 'Sales Person', type: 'text', required: true },
        { name: 'client_name', label: 'Client Name', type: 'text', required: true },
        { name: 'contact_no', label: 'Contact No', type: 'tel', required: true },
        { name: 'email', label: 'Email', type: 'email', required: false },
    ],
    partner_on_board: [
        { name: 'date', label: 'Date', type: 'date', required: true },
        { name: 'partner_name', label: 'Partner Name', type: 'text', required: true },
        { name: 'partner_type', label: 'Partner Type', type: 'text', required: true },
        { name: 'contact_person', label: 'Contact Person', type: 'text', required: true },
        { name: 'contact_no', label: 'Contact No', type: 'tel', required: false },
        { name: 'region', label: 'Region', type: 'text', required: false },
    ],
    dc_visit: [
        { name: 'date', label: 'Date', type: 'date', required: true },
        { name: 'sales_person', label: 'Sales Person', type: 'text', required: true },
        { name: 'account_name', label: 'Account Name', type: 'text', required: true },
        { name: 'product_pitched', label: 'Product Pitched', type: 'text', required: true },
        { name: 'sector', label: 'Sector', type: 'text', required: true },
        { name: 'region', label: 'Region', type: 'text', required: true },
        { name: 'contact_person', label: 'Contact Person', type: 'text', required: false },
        { name: 'mobile', label: 'Mobile', type: 'tel', required: false },
    ],
    client_direct_visit: [
        { name: 'date', label: 'Date', type: 'date', required: true },
        { name: 'sales_person', label: 'Sales Person', type: 'text', required: true },
        { name: 'client_name', label: 'Client Name', type: 'text', required: true },
        { name: 'products_pitched', label: 'Products Pitched', type: 'text', required: true },
        { name: 'industry', label: 'Industry', type: 'text', required: true },
        { name: 'region', label: 'Region', type: 'text', required: true },
    ],
    events_attend: [
        { name: 'date', label: 'Date', type: 'date', required: true },
        { name: 'event_name', label: 'Event Name', type: 'text', required: true },
        { name: 'location', label: 'Location', type: 'text', required: true },
        { name: 'attendees', label: 'Attendees', type: 'number', required: false },
        { name: 'leads_generated', label: 'Leads Generated', type: 'number', required: false },
    ],
    daily_report: [
        { name: 'date', label: 'Date', type: 'date', required: true },
        { name: 'sales_person', label: 'Sales Person', type: 'text', required: true },
        { name: 'activities', label: 'Activities', type: 'textarea', required: true },
        { name: 'notes', label: 'Notes', type: 'textarea', required: false },
    ],
};

const AddDataForm = ({ sheetType, onSubmit, onCancel }) => {
    const fields = formFields[sheetType] || [];
    const [formData, setFormData] = useState({});
    const [errors, setErrors] = useState({});

    const handleChange = (fieldName, value) => {
        setFormData(prev => ({ ...prev, [fieldName]: value }));
        // Clear error when user types
        if (errors[fieldName]) {
            setErrors(prev => ({ ...prev, [fieldName]: null }));
        }
    };

    const validate = () => {
        const newErrors = {};
        fields.forEach(field => {
            if (field.required && !formData[field.name]) {
                newErrors[field.name] = `${field.label} is required`;
            }
        });
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (validate()) {
            // Add sr_no automatically
            const newRecord = {
                sr_no: Date.now(), // Use timestamp as unique ID
                ...formData,
            };
            onSubmit(newRecord);
            setFormData({});
        }
    };

    const getSheetTitle = () => {
        const titles = {
            order_booked: 'Order Booked',
            payment_collection: 'Payment Collection',
            funnel: 'Funnel',
            proposal_submitted: 'Proposal Submitted',
            demos: 'Demo',
            partner_on_board: 'Partner on Board',
            dc_visit: 'DC Visit',
            client_direct_visit: 'Client Direct Visit',
            events_attend: 'Events Attend',
            daily_report: 'Daily Report',
        };
        return titles[sheetType] || 'Add Data';
    };

    return (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-fadeIn overflow-y-auto">
            <div className="glass rounded-2xl shadow-2xl max-w-3xl w-full border-2 border-white/20 my-8 animate-scaleIn">
                {/* Header */}
                <div className="flex items-center justify-between p-6 border-b border-white/20 sticky top-0 bg-white/70 backdrop-blur-md z-10">
                    <div className="flex items-center gap-3">
                        <div className="p-3 bg-gradient-to-br from-blue-500 to-purple-500 rounded-xl">
                            <Plus className="w-6 h-6 text-white" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-bold text-gray-900">Add New Record</h2>
                            <p className="text-sm text-gray-600">{getSheetTitle()}</p>
                        </div>
                    </div>
                    <button
                        onClick={onCancel}
                        className="p-2 hover:bg-white/50 rounded-lg transition-all"
                    >
                        <X className="w-6 h-6 text-gray-600" />
                    </button>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="p-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {fields.map((field) => (
                            <div key={field.name} className={field.type === 'textarea' ? 'md:col-span-2' : ''}>
                                <label className="block text-sm font-semibold text-gray-700 mb-2">
                                    {field.label}
                                    {field.required && <span className="text-red-500 ml-1">*</span>}
                                </label>

                                {field.type === 'select' ? (
                                    <select
                                        value={formData[field.name] || ''}
                                        onChange={(e) => handleChange(field.name, e.target.value)}
                                        className={`w-full px-4 py-3 border-2 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent transition-all ${errors[field.name] ? 'border-red-500' : 'border-gray-300'
                                            }`}
                                    >
                                        <option value="">Select {field.label}</option>
                                        {field.options.map(option => (
                                            <option key={option} value={option}>{option}</option>
                                        ))}
                                    </select>
                                ) : field.type === 'textarea' ? (
                                    <textarea
                                        value={formData[field.name] || ''}
                                        onChange={(e) => handleChange(field.name, e.target.value)}
                                        rows={3}
                                        className={`w-full px-4 py-3 border-2 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent transition-all ${errors[field.name] ? 'border-red-500' : 'border-gray-300'
                                            }`}
                                        placeholder={`Enter ${field.label}`}
                                    />
                                ) : (
                                    <input
                                        type={field.type}
                                        value={formData[field.name] || ''}
                                        onChange={(e) => handleChange(field.name, e.target.value)}
                                        className={`w-full px-4 py-3 border-2 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent transition-all ${errors[field.name] ? 'border-red-500' : 'border-gray-300'
                                            }`}
                                        placeholder={`Enter ${field.label}`}
                                    />
                                )}

                                {errors[field.name] && (
                                    <p className="text-red-500 text-sm mt-1">{errors[field.name]}</p>
                                )}
                            </div>
                        ))}
                    </div>

                    {/* Footer */}
                    <div className="flex justify-end gap-3 mt-6 pt-6 border-t border-gray-200">
                        <button
                            type="button"
                            onClick={onCancel}
                            className="px-6 py-3 bg-white border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-medium transition-all"
                        >
                            Cancel
                        </button>
                        <button
                            type="submit"
                            className="px-6 py-3 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-lg hover:shadow-lg transform hover:-translate-y-0.5 transition-all duration-200 font-medium flex items-center gap-2"
                        >
                            <Save className="w-5 h-5" />
                            Save Record
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default AddDataForm;
