import * as XLSX from 'xlsx';

/**
 * Parse Excel file and extract data from all sheets
 * @param {File} file - Excel file to parse
 * @returns {Promise<Object>} Parsed data with sheet information
 */
export const parseExcelFile = async (file) => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();

        reader.onload = (e) => {
            try {
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, { type: 'array' });

                const parsedData = {
                    filename: file.name,
                    size: file.size,
                    uploadDate: new Date().toISOString(),
                    sheets: []
                };

                // Process each sheet
                workbook.SheetNames.forEach(sheetName => {
                    const worksheet = workbook.Sheets[sheetName];
                    const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: null });

                    if (jsonData.length > 0) {
                        const headers = jsonData[0];
                        const rows = jsonData.slice(1).filter(row => row.some(cell => cell !== null && cell !== ''));

                        parsedData.sheets.push({
                            name: sheetName,
                            headers: headers,
                            totalRows: rows.length,
                            totalColumns: headers.length,
                            preview: rows.slice(0, 10).map(row => {
                                const rowData = {};
                                headers.forEach((header, index) => {
                                    rowData[header] = row[index];
                                });
                                return rowData;
                            }),
                            allData: rows.map(row => {
                                const rowData = {};
                                headers.forEach((header, index) => {
                                    rowData[header] = row[index];
                                });
                                return rowData;
                            })
                        });
                    }
                });

                resolve(parsedData);
            } catch (error) {
                reject(new Error(`Failed to parse Excel file: ${error.message}`));
            }
        };

        reader.onerror = () => {
            reject(new Error('Failed to read file'));
        };

        reader.readAsArrayBuffer(file);
    });
};

export const transformToDashboardFormat = (parsedData) => {
    const findSheet = (names) => {
        return parsedData.sheets.find(sheet =>
            names.some(name => sheet.name.toLowerCase().includes(name.toLowerCase()))
        );
    };

    // Find all sheets by common names
    const orderBookedSheet = findSheet(['order booked', 'order', 'orders']);
    const paymentCollectionSheet = findSheet(['payment collection', 'payment', 'collections']);
    const funnelSheet = findSheet(['funnel']);
    const proposalSheet = findSheet(['proposal submitted', 'proposal', 'proposals']);
    const demoSheet = findSheet(['demo', 'demos']);
    const partnerSheet = findSheet(['partner on board', 'partner', 'partners']);
    const dcVisitSheet = findSheet(['dc visit', 'dc visits', 'data center']);
    const visitSheet = findSheet(['client direct visit', 'client visit', 'visits']);
    const eventsSheet = findSheet(['events attend', 'events', 'event']);
    const dailyReportSheet = findSheet(['daily report', 'daily', 'report']);

    // Helper to normalize field names
    const normalizeFieldName = (name) => {
        return String(name || '')
            .toLowerCase()
            .replace(/\s+/g, '_')
            .replace(/[^\w_]/g, '')
            .replace(/_+/g, '_')
            .replace(/^_|_$/g, '');
    };

    // Helper to map row data
    const mapRowData = (row, fieldMapping) => {
        const mapped = {};
        Object.keys(row).forEach(key => {
            const normalizedKey = normalizeFieldName(key);
            const mappedKey = fieldMapping[normalizedKey] || normalizedKey;
            mapped[mappedKey] = row[key];
        });
        return mapped;
    };

    // Generic processor for any sheet
    const processGenericSheet = (sheet) => {
        if (!sheet) return [];
        return sheet.allData.map((row, idx) => {
            const processed = { sr_no: idx + 1 };
            Object.keys(row).forEach(key => {
                if (key && row[key] !== null && row[key] !== undefined) {
                    const normalizedKey = normalizeFieldName(key);
                    processed[normalizedKey] = row[key];
                }
            });
            return processed;
        });
    };

    // Process Order Booked
    const orderBooked = processGenericSheet(orderBookedSheet);

    // Process Payment Collection
    const paymentCollection = processGenericSheet(paymentCollectionSheet);

    // Process Funnel
    const funnel = processGenericSheet(funnelSheet);

    // Process proposals
    const proposals = proposalSheet ? proposalSheet.allData.map((row, idx) => {
        const fieldMapping = {
            'sr_no': 'sr_no',
            'sr_no_': 'sr_no',
            'date': 'date',
            'pot_id': 'pot_id',
            'source_direct_channel_alliance_partner': 'source',
            'source': 'source',
            'sales_person': 'sales_person',
            'client_name_account_name': 'client_name',
            'client_name': 'client_name',
            'account_name': 'client_name',
            'opportunity_name': 'opportunity_name',
            'mrr': 'mrr',
            'acv': 'acv',
            'otc': 'otc',
            'tcv': 'tcv',
            'sales_stage_l1_l6': 'sales_stage',
            'sales_stage': 'sales_stage',
            'probability': 'probability',
            'probability_': 'probability',
            'sales_type_net_new_upsell_existing': 'sales_type',
            'sales_type': 'sales_type',
            'industry': 'industry',
            'region': 'region',
            'remark': 'remark',
            'latest_remark': 'latest_remark'
        };

        const mapped = mapRowData(row, fieldMapping);
        return {
            sr_no: mapped.sr_no || (idx + 1),
            date: mapped.date,
            pot_id: mapped.pot_id,
            source: mapped.source,
            sales_person: mapped.sales_person,
            client_name: mapped.client_name,
            opportunity_name: mapped.opportunity_name,
            mrr: parseFloat(mapped.mrr) || 0,
            acv: parseFloat(mapped.acv) || 0,
            otc: parseFloat(mapped.otc) || 0,
            tcv: parseFloat(mapped.tcv) || 0,
            sales_stage: mapped.sales_stage,
            probability: parseFloat(mapped.probability) || 0,
            sales_type: mapped.sales_type,
            industry: mapped.industry,
            region: mapped.region,
            remark: mapped.remark,
            latest_remark: mapped.latest_remark
        };
    }) : [];

    // Process demos
    const demos = demoSheet ? demoSheet.allData.map((row, idx) => ({
        sr_no: row['Sr. No'] || row['Sr No'] || row['Sr.No'] || (idx + 1),
        sales_person: row['Sales person'] || row['Sales Person'] || row['SalesPerson'],
        client_name: row['Client Name'] || row['Client'] || row['ClientName'],
        contact_no: row['Contact No'] || row['Contact'] || row['ContactNo'],
        email: row['Email'] || row['email'] || row['E-mail']
    })) : [];

    // Process Partner on board
    const partners = processGenericSheet(partnerSheet);

    // Process client visits
    const visits = visitSheet ? visitSheet.allData.map((row, idx) => ({
        sr_no: row['Sr. No'] || row['Sr No'] || (idx + 1),
        date: row['Date'],
        sales_person: row['Sales person'] || row['Sales Person'],
        client_name: row['Client Name/ Account Name'] || row['Client Name'] || row['Client'],
        products_pitched: row['Products/ Services Pitched'] || row['Products Pitched'] || row['Products'],
        industry: row['Industry'],
        region: row['Region']
    })) : [];

    // Process DC visits
    const dcVisits = dcVisitSheet ? dcVisitSheet.allData.map((row, idx) => ({
        sr_no: row['Sr. No'] || row['Sr No'] || (idx + 1),
        date: row['Date'],
        sales_person: row['Sales Person'] || row['Sales person'],
        account_name: row['Account /Client Name'] || row['Account Name'] || row['Account'],
        product_pitched: row['Product Pitched in'] || row['Product Pitched'] || row['Product'],
        sector: row['Sector'],
        region: row['Region'],
        contact_person: row['Contact person'] || row['Contact Person'],
        mobile: row['Mobile number'] || row['Mobile']
    })) : [];

    // Process Events Attend
    const events = processGenericSheet(eventsSheet);

    // Process Daily Report
    const dailyReport = processGenericSheet(dailyReportSheet);

    // Calculate KPIs
    const totalTCV = proposals.reduce((sum, p) => sum + (p.tcv || 0), 0);
    const avgACV = proposals.length > 0
        ? proposals.reduce((sum, p) => sum + (p.acv || 0), 0) / proposals.length
        : 0;
    const avgProbability = proposals.length > 0
        ? proposals.reduce((sum, p) => sum + (p.probability || 0), 0) / proposals.length
        : 0;

    return {
        metadata: {
            report_name: 'Uploaded Sales Funnel Data',
            generated_at: new Date().toISOString(),
            source: 'excel_upload',
            filename: parsedData.filename,
            total_sheets: parsedData.sheets.length
        },
        sheets: {
            order_booked: {
                sheet_name: 'Order Booked',
                total_records: orderBooked.length,
                data: orderBooked
            },
            payment_collection: {
                sheet_name: 'Payment Collection',
                total_records: paymentCollection.length,
                data: paymentCollection
            },
            funnel: {
                sheet_name: 'Funnel',
                total_records: funnel.length,
                data: funnel
            },
            proposal_submitted: {
                sheet_name: 'Proposal Submitted',
                total_records: proposals.length,
                data: proposals,
                summary: {
                    total_proposals: proposals.length,
                    total_tcv: totalTCV,
                    avg_acv: avgACV,
                    avg_probability: avgProbability
                }
            },
            demos: {
                sheet_name: 'Demo',
                total_records: demos.length,
                data: demos
            },
            partner_on_board: {
                sheet_name: 'Partner on board',
                total_records: partners.length,
                data: partners
            },
            client_direct_visit: {
                sheet_name: 'Client Direct Visit',
                total_records: visits.length,
                data: visits
            },
            dc_visit: {
                sheet_name: 'DC Visit',
                total_records: dcVisits.length,
                data: dcVisits
            },
            events_attend: {
                sheet_name: 'Events Attend',
                total_records: events.length,
                data: events
            },
            daily_report: {
                sheet_name: 'Daily Report',
                total_records: dailyReport.length,
                data: dailyReport
            }
        },
        kpis: {
            total_proposals: proposals.length,
            total_demos_conducted: demos.length,
            total_client_visits: visits.length,
            total_dc_visits: dcVisits.length,
            total_orders_booked: orderBooked.length,
            total_payments: paymentCollection.length,
            total_partners: partners.length,
            total_events: events.length,
            total_funnel_activities: proposals.length + demos.length + visits.length + dcVisits.length + orderBooked.length + events.length,
            revenue_metrics: {
                total_tcv: totalTCV,
                avg_acv: avgACV,
                avg_deal_probability: avgProbability
            }
        }
    };
};

/**
 * Validate Excel file
 * @param {File} file - File to validate
 * @returns {Object} Validation result
 */
export const validateExcelFile = (file) => {
    const maxSize = 10 * 1024 * 1024; // 10MB
    const allowedTypes = [
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', // .xlsx
        'application/vnd.ms-excel', // .xls
    ];

    if (!file) {
        return { valid: false, error: 'No file selected' };
    }

    if (file.size > maxSize) {
        return { valid: false, error: `File size exceeds 10MB limit (${(file.size / 1024 / 1024).toFixed(2)}MB)` };
    }

    // Check file extension as fallback
    const fileName = file.name.toLowerCase();
    if (!fileName.endsWith('.xlsx') && !fileName.endsWith('.xls')) {
        return { valid: false, error: 'Invalid file type. Please upload .xlsx or .xls file' };
    }

    return { valid: true };
};
