import React, { useState } from 'react';
import EnhancedTable from '../components/EnhancedTable';
import FilterPanel from '../components/FilterPanel';
import AddDataForm from '../components/AddDataForm';
import { useDashboardData } from '../utils/dashboardDataHook';
import { columnDefinitions } from '../utils/columnDefinitions';

const ReportPage = ({ sheetKey, title }) => {
    const {
        aggregatedData,
        filters,
        setFilters,
        searchTerm,
        setSearchTerm,
        availableFilters,
        addRecord,
        deleteRecord
    } = useDashboardData();

    const [showAddForm, setShowAddForm] = useState(false);

    // Get data for this specific sheet
    const rawData = aggregatedData?.sheets?.[sheetKey]?.data || [];

    // Filter data
    const filteredData = rawData.filter(item => {
        // Apply search
        if (searchTerm) {
            const searchLower = searchTerm.toLowerCase();
            const matchesSearch = Object.values(item).some(value =>
                value && String(value).toLowerCase().includes(searchLower)
            );
            if (!matchesSearch) return false;
        }

        // Apply filters
        for (const [key, value] of Object.entries(filters)) {
            if (value && item[key] !== value) {
                return false;
            }
        }

        return true;
    });

    const columns = columnDefinitions[sheetKey] || [];

    const handleAddData = (newRecord) => {
        addRecord(sheetKey, newRecord);
        setShowAddForm(false);
    };

    const handleDeleteData = (index) => {
        if (window.confirm('Are you sure you want to delete this record?')) {
            deleteRecord(sheetKey, index);
        }
    };

    if (!aggregatedData) {
        return (
            <div className="flex items-center justify-center h-64">
                <p className="text-gray-500">Please upload data from the Dashboard to view reports.</p>
            </div>
        );
    }

    return (
        <div className="p-4 sm:p-8 animate-fadeIn">
            <div className="max-w-7xl mx-auto">
                <div className="mb-8">
                    <h1 className="text-3xl font-bold text-gray-900 mb-2">{title}</h1>
                    <p className="text-gray-600">
                        Showing {filteredData.length} records from {aggregatedData.metadata.filename}
                    </p>
                </div>

                <FilterPanel
                    filters={filters}
                    onFilterChange={(key, value) => setFilters(prev => ({ ...prev, [key]: value }))}
                    onSearch={setSearchTerm}
                    searchTerm={searchTerm}
                    availableFilters={availableFilters}
                />

                <div className="mt-8">
                    <EnhancedTable
                        title={`${title} List`}
                        data={filteredData}
                        columns={columns}
                        onAddData={() => setShowAddForm(true)}
                        onDelete={handleDeleteData}
                    />
                </div>

                {showAddForm && (
                    <AddDataForm
                        sheetType={sheetKey}
                        onSubmit={handleAddData}
                        onCancel={() => setShowAddForm(false)}
                    />
                )}
            </div>
        </div>
    );
};

export default ReportPage;
